  "own.recusal": "کوئی رکن کسی معاملے سے الگ نہیں ہو سکتا۔ یہ درج کرنے کا کہیں کوئی انتظام نہیں کہ کسی کا اس سوال میں مفاد ہے اور اس نے حصہ نہیں لیا — سو جو بورڈ کسی کو الگ کرتا ہے وہ اسے اس ایپلیکیشن سے باہر درج کرتا ہے، اور یہاں کی گنتی اسے بس اُن میں شمار کرتی ہے جنہوں نے ووٹ نہیں دیا۔",
  "own.ratify": "ممانعت کی توثیق نہیں ہو سکتی۔ وہ کم نصاب پر نافذ ہوتی ہے، مدت چلتی ہے، اور مدت ختم ہوتے ہی ساقط ہو جاتی ہے — اور اسے روکنے کا کوئی راستہ نہیں، کیونکہ عمل سافٹ ویئر میں ہے، کوئی راستہ اس تک نہیں پہنچتا، اور کہیں درج نہیں ہوتا کہ ہوا۔ تقویم ایسی تاریخ کی الٹی گنتی کر رہا ہے جس کے لیے کوئی کچھ نہیں کر سکتا۔",
  "own.whoReports": "خلاف ورزی کون رپورٹ کرتا ہے، یہ طے نہیں۔ دستخط کنندہ، مشاورتی رکن اور ادارے کا رابطہ کار رپورٹ کر سکتے ہیں؛ ادارے کا اپنا ڈیسک نہیں کر سکتا، اور نہ بورڈ سے باہر کوئی۔ تطہیر کون ادا کرتا ہے، یہ درج ہی نہیں ہوتا — صرف یہ کہ کیا مقرر ہوا۔",
