  "set.gap.noInstitutionSignIn": "ادارہ داخل نہیں ہو سکتا۔ کردار موجود ہے اور بینک کے ڈیسک کے لیے ہر اسکرین بنی ہوئی ہے، مگر اس کے لیے کوئی سند جاری نہیں ہو سکتی، سو اس بورڈ سے باہر کوئی بھی ان تک نہیں پہنچ سکتا۔ جب تک یہ نہ بنے، ادارہ جو کچھ دیکھتا ہے وہ کوئی شخص اس تک پہنچاتا ہے۔",
